  if (LONG_OPTIONS.includes(name)) {
    return name;
  }

  const matches = LONG_OPTIONS.filter((option) => option.startsWith(name));
  return matches.length === 1 ? matches[0] : null;
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test17.mjs';
  }
  return basename(scriptPath);
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --key KEY --iv IV --data DATA`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help   show this help message and exit\n  --key KEY\n  --iv IV\n  --data DATA\n`;
}

