  }

  const out = new Uint8Array(left.length);
  for (let index = 0; index < left.length; index += 1) {
    out[index] = left[index] ^ right[index];
  }

  return out;
}

export function splitBlocks(bytes, blockSize) {
  const blocks = [];
  for (let index = 0; index < bytes.length; index += blockSize) {
    blocks.push(bytes.subarray(index, index + blockSize));
  }
  return blocks;
}

export function toPythonBytesLiteral(bytes) {
  let hasSingleQuote = false;
  let hasDoubleQuote = false;

  for (const value of bytes) {
    if (value === 0x27) {
      hasSingleQuote = true;
    } else if (value === 0x22) {
      hasDoubleQuote = true;
    }
  }

  const quote = hasSingleQuote && !hasDoubleQuote ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);
  let result = `b${quote}`;

  for (const value of bytes) {
    if (value === 0x09) {
      result += '\\t';
      continue;
    }

    if (value === 0x0a) {
      result += '\\n';
      continue;
    }

    if (value === 0x0d) {
      result += '\\r';
      continue;
    }

    if (value === 0x5c) {
      result += '\\\\';
      continue;
