    if (value === quoteCode) {
      result += `\\${quote}`;
      continue;
    }

    if (value >= 0x20 && value <= 0x7e) {
      result += String.fromCharCode(value);
      continue;
    }

    result += `\\x${value.toString(16).padStart(2, '0')}`;
  }

  result += quote;
  return result;
}
